class MultiHeadCausalAttention(nn.Module):
    def __init__(self, d_model, num_heads, block_size, dropout=0.1):
        super().__init__()
        if d_model % num_heads != 0:
            raise ValueError("d_model must be divisible by num_heads")
        head_dim = d_model // num_heads
        self.heads = nn.ModuleList([
            CausalSelfAttentionHead(d_model, head_dim, block_size, dropout)
            for _ in range(num_heads)
        ])
        self.projection = nn.Linear(d_model, d_model)
        self.dropout = nn.Dropout(dropout)

    def forward(self, x):
        combined = torch.cat([head(x) for head in self.heads], dim=-1)
        return self.dropout(self.projection(combined))

multihead = MultiHeadCausalAttention(
    d_model=64,
    num_heads=4,
    block_size=32
)
print("Multi-head output:", multihead(torch.randn(2, 12, 64)).shape)

@torch.no_grad()
def generate(model, start_text, max_new_tokens=100, temperature=1.0):
    if temperature <= 0:
        raise ValueError("temperature must be positive")
    model.eval()
    unknown = [ch for ch in start_text if ch not in stoi]
    if unknown:
        raise ValueError(f"Prompt contains characters outside the vocabulary: {unknown}")

    context = torch.tensor(
        [[stoi[ch] for ch in start_text]],
        dtype=torch.long,
        device=next(model.parameters()).device
    )
    for _ in range(max_new_tokens):
        context_window = context[:, -model.block_size:]
        logits, _ = model(context_window)
        next_logits = logits[:, -1, :] / temperature
        probabilities = F.softmax(next_logits, dim=-1)
        next_id = torch.multinomial(probabilities, num_samples=1)
        context = torch.cat([context, next_id], dim=1)

    return "".join(itos[i] for i in context[0].tolist())

print(generate(model, "transform", max_new_tokens=100, temperature=0.8))
